export const AUTH_HTTP_ERROR = 'AUTH_HTTP_ERROR'
export const AUTH_ERROR_MESSAGE = 'AUTH_ERROR_MESSAGE'

export function authHttpError(authHttpError) {
  return {
    type: AUTH_HTTP_ERROR,
    authHttpError: authHttpError
  }
}


export function authErrorMessage(authErrorMessage) {
  return {
    type: AUTH_ERROR_MESSAGE,
    authHttpError: authErrorMessage
  }
}

export function fetchAuth() {
  console.log('fetch auth');
  return dispatch => {
    //dispatch(requestAuth())
    return fetch('https://scbm.amfdev.co.uk/api/auth/', {
      method: "GET",
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Cache': 'no-cache'
      },
      credentials: 'include'
      })
      .then(response => catchAuthHttpError(response, dispatch))
      .then(response => response.json())
      .then(json => catchAuthErrorMessage(json, dispatch))
      //.then(catchAuthResult)
      //.then(catchAuthInvalidCookies)
      //.then(doAuthSuccess)
      .catch(error => console.log(error));
  }

}

// Handle HTTP errors since fetch won't.
function catchAuthHttpError(response, dispatch) {
   console.log('catchAuthHttpError')
  if (!response.ok) {
     dispatch(authHttpError(response.statusText))
    throw Error(response.statusText);
  }
  return response;
}


// Handle HTTP errors since fetch won't.
function catchAuthErrorMessage(json, dispatch) {
   console.log('catchAuthErrorMessage')
    if (json.errorMessage) {
        dispatch(authErrorMessage(json.errorMessage))
        throw Error(json.errorMessage);
    }
    
  return json;
}


